NAMES = ['HLT', 'LDI', 'ADD', 'SUB', 'STA', 'LDA', 'JMP', 'JNZ', 'OUT']
CYC = [1, 2, 2, 2, 3, 3, 3, 3, 2]

def run_toy(program, max_steps):
    mem = list(program) + [0] * (256 - len(program))
    pc = 0
    a = 0
    z = False
    out = []
    cycles = 0
    halted = 0
    for _ in range(max_steps):
        op = mem[pc & 255]
        n = mem[(pc + 1) & 255]
        pc = (pc + LEN[op]) & 255 if op < 9 else pc
        cycles += CYC[op]
        if op == 0:
            halted = 1
            break
        elif op == 1:
            a = n
            z = a == 0
        elif op == 2:
            a = (a + n) & 255
            z = a == 0
        elif op == 3:
            a = (a - n) & 255
            z = a == 0
        elif op == 4:
            mem[n] = a
        elif op == 5:
            a = mem[n]
            z = a == 0
        elif op == 6:
            pc = n
        elif op == 7:
            if not z:
                pc = n
            else:
                cycles -= 1
        elif op == 8:
            out.append(a)
    return [out, cycles, a, halted]

