def chip8_decode(op):
    # your code
    pass

practice.solution:
def chip8_decode(op):
    h = '0123456789abcdef'
    x = (op >> 8) & 15
    nn = op & 255
    nnn = op & 4095
    def hx(v, n):
        s = ''
        for i in range(n):
            s = h[v & 15] + s
            v = v >> 4
        return s
    if op == 0x00E0:
        return 'CLS'
    if op == 0x00EE:
        return 'RET'
    t = op >> 12
    if t == 1:
        return 'JP ' + hx(nnn, 3)
    if t == 6:
        return 'LD V' + hx(x, 1) + ',' + hx(nn, 2)
    if t == 7:
        return 'ADD V' + hx(x, 1) + ',' + hx(nn, 2)
    if t == 0xA:
        return 'LD I,' + hx(nnn, 3)
    return 'UNKNOWN'

