def chip8_exec(ops):
    v = [0] * 16
    for op in ops:
        t = op >> 12
        x = (op >> 8) & 15
        y = (op >> 4) & 15
        nn = op & 255
        if t == 6:
            v[x] = nn
        elif t == 7:
            v[x] = (v[x] + nn) & 255
        elif t == 8 and (op & 15) == 4:
            s = v[x] + v[y]
            v[x] = s & 255
            v[15] = 1 if s > 255 else 0
    return v

