def basic_blocks(program):
    lens = [1, 2, 2, 2, 2, 2, 2, 2, 1]
    leaders = set([0])
    pc = 0
    while pc < len(program):
        op = program[pc]
        n = lens[op] if op < 9 else 1
        if op == 6 or op == 7:
            t = program[pc + 1]
            if t < len(program):
                leaders.add(t)
        if op in (0, 6, 7):
            if pc + n < len(program):
                leaders.add(pc + n)
        pc += n
    return sorted(leaders)

